
// the menus' backgrounds: five pictures, the next one each time the screen changes (and the next again at each launch)
(function(){
  var SRC = [
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,'
  ];
  // (as blob: links -- one short name per picture, so the browser decodes each once and swaps them cheaply)
  var urls = SRC.map(function(u){
    try {
      var b = atob(u.slice(u.indexOf(',') + 1)), a = new Uint8Array(b.length);
      for(var i = 0; i < b.length; i++) a[i] = b.charCodeAt(i);
      return URL.createObjectURL(new Blob([a], { type:'image/webp' }));
    } catch(e){ return u; }
  });
  SRC = null;
  var bd = document.getElementById('menu-backdrop'), L = [document.getElementById('mbd-a'), document.getElementById('mbd-b')];
  var cur = 0, idx = 0, token = 0, KEY = 'spaghettify.menuBg', imgs = {};
  try { var was = parseInt(localStorage.getItem(KEY), 10); if(was >= 0) idx = (was + 1) % urls.length; } catch(e){}
  function remember(){ try { localStorage.setItem(KEY, String(idx)); } catch(e){} }
  function paint(layer, i){ var u = 'url("' + urls[i] + '")'; layer.children[0].style.backgroundImage = u; layer.children[1].style.backgroundImage = u; }
  function ready(i, cb){                                   // decoded before it fades in: no blank frames mid-fade
    var im = imgs[i]; if(!im){ im = imgs[i] = new Image(); im.src = urls[i]; }
    if(im.decode) im.decode().then(cb, cb); else if(im.complete) cb(); else { im.onload = cb; im.onerror = cb; }
  }
  function warmNext(){                                     // the one after this, decoded ahead (the rest let go)
    var n = (idx + 1) % urls.length, keep = {}; keep[idx] = imgs[idx]; keep[n] = imgs[n]; imgs = keep;
    setTimeout(function(){ ready(n, function(){}); }, 1500);
  }
  paint(L[0], idx); remember(); warmNext();
  function next(){
    // (the title moves on when the screen now on top shows one: so every visit to a titled menu gets the other title)
    if(window.menuTitleNext && topEl && topEl.querySelector && topEl.querySelector('.menu-logo')) try { window.menuTitleNext(); } catch(e){}
    idx = (idx + 1) % urls.length; remember();
    var my = ++token, inL = L[1 - cur], outL = L[cur];
    paint(inL, idx);
    ready(idx, function(){
      if(my !== token) return;                             // (a newer change came in meanwhile)
      inL.classList.add('on'); outL.classList.remove('on'); cur = 1 - cur;
      warmNext();
    });
  }
  window.menuBackdropNext = next;
  // 3D mode: stars drifting toward you in front of the picture (drawn only while a menu is up in 3D mode)
  var sc = document.createElement('canvas'); sc.id = 'bd-stars'; sc.setAttribute('aria-hidden', 'true'); bd.appendChild(sc);
  var stars = [], sOn = false, sLast = 0;
  function star(s, far){ s.x = (Math.random()*2 - 1)*1.4; s.y = (Math.random()*2 - 1)*1.4; s.z = far ? 0.85 + Math.random()*0.15 : 0.1 + Math.random()*0.9; return s; }
  for(var si = 0; si < 150; si++) stars.push(star({}, false));
  function starTick(ts){
    if(bd.classList.contains('off') || !document.body.classList.contains('menu3d')){
      sOn = false; sLast = 0; var x0 = sc.getContext('2d'); if(x0) x0.clearRect(0, 0, sc.width, sc.height); return;
    }
    requestAnimationFrame(starTick);
    if(sLast && ts - sLast < 33) return;                     // (30 frames a second)
    var dt = sLast ? Math.min(0.1, (ts - sLast)/1000) : 0; sLast = ts;
    var dpr = Math.min(1.5, window.devicePixelRatio || 1), W = Math.round(bd.clientWidth*dpr), H = Math.round(bd.clientHeight*dpr);
    if(!W || !H) return;
    if(sc.width !== W || sc.height !== H){ sc.width = W; sc.height = H; }
    var x = sc.getContext('2d'); if(!x) return;
    x.clearRect(0, 0, W, H); x.fillStyle = '#ffeedd';
    var cx = W/2, cy = H/2, f = Math.max(W, H)*0.45;
    for(var k = 0; k < stars.length; k++){
      var s = stars[k]; s.z -= dt*0.055*(window.__menuMotion === undefined ? 1 : window.__menuMotion);
      if(s.z < 0.06){ star(s, true); continue; }
      var px = cx + s.x/s.z*f, py = cy + s.y/s.z*f;
      if(px < -10 || py < -10 || px > W + 10 || py > H + 10){ star(s, true); continue; }
      var near = 1 - s.z;
      x.globalAlpha = Math.min(1, near*1.25); x.beginPath(); x.arc(px, py, (0.3 + near*near*2.2)*dpr, 0, 6.2832); x.fill();
    }
    x.globalAlpha = 1;
  }
  window.menuStars = function(){ if(!sOn){ sOn = true; sLast = 0; requestAnimationFrame(starTick); } };
  // which menu screen is on top: when that changes, the next picture; under a page, the screen beneath isn't drawn;
  // in a game, no backdrop at all
  var IDS = ['title-screen', 'main-menu', 'options-screen', 'game-options-screen', 'world-options-screen', 'gfx-options-screen', 'ctl-options-screen', 'motion-options-screen', 'save-options-screen', 'store-screen', 'hangar-screen'], topEl;   // (bottom to top)
  function scan(){
    var els = [], vis = [], k;
    for(k = 0; k < IDS.length; k++){ var e = document.getElementById(IDS[k]); if(!e) continue; els.push(e); if(getComputedStyle(e).display !== 'none') vis.push(e); }
    var t = vis.length ? vis[vis.length - 1] : null;
    for(k = 0; k < els.length; k++) els[k].classList.toggle('menu-under', !!t && els[k] !== t && vis.indexOf(els[k]) >= 0);
    bd.classList.toggle('off', !t);
    if(t) window.menuStars();
    if(t !== topEl){ var first = topEl === undefined; topEl = t; if(t && !first) next(); }
  }
  function watch(){
    var mo = new MutationObserver(scan);
    for(var k = 0; k < IDS.length; k++){ var e = document.getElementById(IDS[k]); if(e) mo.observe(e, { attributes:true, attributeFilter:['style'] }); }
    scan();
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', watch); else watch();
})();
